// hardware_config.h -- pin assignments and physical timing for this build.
//
// HAND-WRITTEN. Do not move any of this into model_settings.h: that file is
// regenerated by scripts/quantize.py on every model export, which would wipe
// these definitions silently. model_settings.h owns labels, input shape and
// sample rate; this file owns everything that depends on how the board is
// physically wired.
//
// Board wiring (see docs/hardware.md for the full picture):
//
//   D2 --[330R]--> LED anode (long leg)
//                  LED cathode (short leg) --> GND
//
// The resistor value matters more than it looks. The nRF52840 drives a pin at
// roughly 2 mA in its default "standard drive" mode, and allows only ~15 mA on
// any one pin and ~25 mA across all pins plus VDD combined -- a budget already
// shared with the onboard RGB LED. 330R against a red LED's ~2.0 V forward
// drop gives about 4 mA from the 3.3 V rail: clearly visible, comfortably
// inside the budget.
//
// Use a red, yellow, or amber LED. Blue and white LEDs drop 3.0-3.2 V, leaving
// almost nothing across the resistor from a 3.3 V rail -- they come out dim and
// vary noticeably part to part.

#ifndef HARDWARE_CONFIG_H_
#define HARDWARE_CONFIG_H_

#include <Arduino.h>

// --- Action LED -----------------------------------------------------------
// The physical output: driven high on "play", low on "pause". Ordinary
// active-HIGH wiring, unlike the onboard RGB LED below.
constexpr int kActionLedPin = 2;

// --- Status LED -----------------------------------------------------------
// The onboard RGB LED (pins 22/23/24) is ACTIVE LOW: LOW turns a channel on.
// Separate from the action LED on D2 -- this one reports what the spotter is
// doing (settling / listening / accepted / rejected), not what it decided.
//
// Driven with digitalWrite rather than analogWrite: the mbed core has been
// reported to crash with PWM active on more than three pins, and nothing here
// needs brightness control.
constexpr int kLedRedPin = LEDR;
constexpr int kLedGreenPin = LEDG;
constexpr int kLedBluePin = LEDB;

// How long an accept/reject color stays lit before reverting to listening.
constexpr uint32_t kStatusFlashMs = 400;

// --- Microphone -----------------------------------------------------------
// The onboard PDM mic returns unreliable data for roughly the first 3.5 s
// after power-up or reset. Without this window the board fires phantom
// detections the instant it is plugged in. Rounded up for margin.
constexpr uint32_t kMicSettleMs = 4000;

// PDM gain. This value MUST match the one in firmware/AudioCapture, which is
// what records the training set. Training on audio captured at one gain and
// running inference at another reintroduces exactly the train/deploy mismatch
// that recording on the Nano was meant to eliminate. If you retune it here,
// retune it there and re-record.
//
// Scale is the raw nRF52840 PDM gain register: 0..80, 0.5 dB per step, with
// 40 as 0 dB and 80 the +20 dB maximum. The PDM library does not clamp, so
// stay inside that range.
//
// Measured on this build, speech at normal volume and distance:
//   gain 40 -> ~4% peak      (0 dB reference)
//   gain 72 -> ~20% peak     (+16 dB, measured 5.5x on recorded clips)
//   gain 80 -> ~32% expected (+20 dB, the register maximum)
// 80 is as high as the hardware goes. Quieter-than-usual speech was dipping
// under 20% at 72, so this trades some clipping headroom for that margin --
// a shout may now clip, ordinary speech will not. Note this raises the noise
// floor along with the signal: it buys quantisation headroom, not SNR.
constexpr int kPdmGain = 80;

#endif  // HARDWARE_CONFIG_H_
